import{_ as i,o as t,c as r,a5 as a}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Credit price CSV import","description":"","frontmatter":{},"headers":[],"relativePath":"feature/credit-price-csv-import/spec.md","filePath":"feature/credit-price-csv-import/spec.md"}'),o={name:"feature/credit-price-csv-import/spec.md"};function n(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="credit-price-csv-import" tabindex="-1">Credit price CSV import <a class="header-anchor" href="#credit-price-csv-import" aria-label="Permalink to &quot;Credit price CSV import&quot;">​</a></h1><h2 id="objective-and-contract" tabindex="-1">Objective and contract <a class="header-anchor" href="#objective-and-contract" aria-label="Permalink to &quot;Objective and contract&quot;">​</a></h2><p>Admin imports <code>credit_recommendations.csv</code> produced by the standalone benchmark tool, reviews current/proposed operation prices and source metadata, then applies the reviewed file. Source contract: <code>benmark tool/CREDIT_CSV.md</code> and <code>src/Benchmark.Core/CreditRecommendations.cs</code>, inspected 2026-10-28.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Only an active system Admin can preview/apply; check server-side.</li><li>UTF-8 with optional BOM, RFC4180 quoting/newlines, comma delimiter and exact ordered header: schema_version,operation,unit_credits,source_report_id,profile_id, width,height,steps,generated_at. Maximum 64 KiB; one or two data records.</li><li>schema_version=1; only AMBASSADOR_GENERATE and COMMERCIAL_IMAGE, no duplicates. Credit is an unsigned integer, including deliberate zero, within the existing Web editing range 0..9007199254740991. Values beyond that range are rejected explicitly, never rounded (the benchmark tool itself allows Int64 values).</li><li>Validate report GUID-N, nonblank bounded profile, image dimensions 256..2752 divisible by 32, optional positive Int32 steps, and ISO8601 UTC export timestamp. Source metadata informs review/audit, not resolution/model-specific pricing.</li><li>Preview writes no prices. Show each current/proposed price, revision, preserved enabled state, report/profile/dimensions/steps/export time and record/field errors.</li><li>Apply reparses the uploaded file and verifies its preview SHA256 and exact set of expected revisions. Lock operations in a deterministic order; one transaction updates all changed prices and audit, or rolls back everything on any conflict.</li><li>Preserve current enabled/disabled state. New operation prices remain disabled until explicitly enabled through the existing controls. Unchanged prices do not create revisions. Other operations, wallets/limits and existing reservations stay untouched; accepted AI jobs retain their already-fixed price revision.</li><li>Repeating a changed request with old revisions returns stale; no automatic retry.</li><li>No new tables/migration/init/seeder, no shared DB apply or automatic benchmark run.</li></ul><h2 id="ui-and-states" tabindex="-1">UI and states <a class="header-anchor" href="#ui-and-states" aria-label="Permalink to &quot;UI and states&quot;">​</a></h2><p>On <code>/admin/credit-prices</code>, Import CSV opens the file picker directly. Selection loads an inline review panel; Apply is explicit and disabled on errors, stale preview or while busy. Keep the selected file on recoverable errors; refreshing the preview requires another review before Apply. No additional upload modal.</p><p>All new strings use parallel <code>credit.csv.*</code> vi/en keys. Use existing tokens and Button/Input/Badge, responsive cards for at most two records, light/dark contrast, keyboard focusable error summary and live pending/success states.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><ul><li>POST <code>/api/v1/admin/credit/prices/import/preview</code>: multipart <code>file</code>; preview DTO with SHA256, rows/current state and structured issues; no persistent upload.</li><li>POST <code>/api/v1/admin/credit/prices/import/apply</code>: same <code>file</code> plus JSON part <code>request</code> containing SHA256 and expectedRevisions. Returns changed prices and unchanged operations. Revisions/current price strings avoid metadata precision loss.</li><li>Standard ApiResponse. Invalid file 400, oversized 413, stale/hash mismatch 409, forbidden 403. Audit uses the existing append-only admin audit infrastructure.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Changing benchmark formulas/export format, live usage/token/GPU metering, buying credits, adding operations, auto-enabling AI or new price dimensions.</p>',12)])])}const m=i(o,[["render",n]]);export{h as __pageData,m as default};
